import { Context } from './context'
import { Hono } from './hono'
import { setCookie } from './helper/cookie'

describe('tmp set-cookie', () => {
  it('direct assignment', () => {
    const c = new Context(new Request('http://localhost/'))
    c.res.headers.append('set-cookie', 'old=1; Path=/')
    c.res = new Response('ok', {
      headers: { 'set-cookie': 'new=2; Path=/' },
    })
    console.log('direct', c.res.headers.getSetCookie())
  })

  it('middleware setCookie before next', async () => {
    const app = new Hono()
    app.use(async (c, next) => {
      setCookie(c, 'old', '1', { path: '/' })
      await next()
    })
    app.get('/', () => {
      return new Response('ok', {
        headers: { 'set-cookie': 'new=2; Path=/' },
      })
    })
    const res = await app.request('/')
    console.log('middleware getter', res.headers.getSetCookie())
  })

  it('middleware c.res before next', async () => {
    const app = new Hono()
    app.use(async (c, next) => {
      c.res.headers.append('set-cookie', 'old=1; Path=/')
      await next()
    })
    app.get('/', () => {
      return new Response('ok', {
        headers: { 'set-cookie': 'new=2; Path=/' },
      })
    })
    const res = await app.request('/')
    console.log('middleware res', res.headers.getSetCookie())
  })
})

