set res(_res: Response | undefined) {
  // Headers staged by `c.header()` live in `#preparedHeaders` until `c.res`
  // is read. Fall back to them so prepared cookies are not lost when a raw
  // Response is assigned before anything has read `c.res`.
  const currentHeaders = this.#res?.headers ?? this.#preparedHeaders
  if (currentHeaders && _res) {
    const hasResponse = !!this.#res
    _res = createResponseInstance(_res.body, _res)
    for (const [k, v] of currentHeaders.entries()) {
      if (k === 'content-type' || k === 'set-cookie') {
        continue
      }
      // Prepared headers keep their previous behavior: only a response that
      // already exists has its headers merged into the assigned response.
      if (hasResponse) {
        _res.headers.set(k, v)
      }
    }

    const cookies = currentHeaders.getSetCookie()
    if (cookies.length) {
      const newCookies = _res.headers.getSetCookie()
      for (const cookie of cookies) {
        // Keep cookies already on the new response and merge in the ones
        // from the current response without duplicating them.
        if (!newCookies.includes(cookie)) {
          _res.headers.append('set-cookie', cookie)
          newCookies.push(cookie)
        }
      }
    }
  }
  if (!_res) {
    // Discarding the response also discards staged headers, otherwise they
    // would be applied to the next response assigned to `c.res`.
    this.#preparedHeaders = undefined
  }
  this.#res = _res
  this.finalized = true
}

