input.newString:
it('Should keep cookies set on c.res when a new Response has its own Set-Cookie header', () => {
  c.res.headers.append('set-cookie', 'middleware=1; Path=/')
  c.res = new Response('ok', {
    headers: {
      'set-cookie': 'handler=2; Path=/',
    },
  })

  const cookies = c.res.headers.getSetCookie()
  expect(cookies.length).toBe(2)
  expect(cookies).toContain('middleware=1; Path=/')
  expect(cookies).toContain('handler=2; Path=/')
})

it('Should keep prepared cookies when assigning a raw Response', () => {
  setCookie(c, 'context', '1', { path: '/' })
  c.res = new Response('ok', {
    headers: {
      'set-cookie': 'handler=2; Path=/',
    },
  })

  expect(c.res.headers.getSetCookie()).toEqual([
    'handler=2; Path=/',
    'context=1; Path=/',
  ])
})

it('Should not duplicate prepared cookies when keeping c.res cookies', () => {
  setCookie(c, 'foo', 'bar', { path: '/' })
  c.res
  c.res = new Response('ok')
  expect(c.res.headers.getSetCookie()).toEqual(['foo=bar; Path=/'])
})

